+
+function isRecord(value: unknown): value is Record<string, unknown> {
+  return typeof value === 'object' && value !== null && !Array.isArray(value);
+}
+
+function formatArrayValue(value: unknown): string {
+  return Array.isArray(value) ? value.map((item) => String(item)).join(', ') : '';
+}
+
+function parseArrayValue(
+  text: string,
+  itemSchema: Record<string, unknown> | undefined
+): { values?: unknown[]; error?: string } {
+  const tokens = text
+    .split(',')
+    .map((item) => item.trim())
+    .filter(Boolean);
+  const itemType = itemSchema?.type;
+
+  if (itemType === 'number' || itemType === 'integer') {
+    const values = tokens.map(Number);
+    const valid = values.every((value) =>
+      itemType === 'integer' ? Number.isInteger(value) : Number.isFinite(value)
+    );
+    return valid
+      ? { values }
+      : { error: `Enter comma-separated ${itemType === 'integer' ? 'integers' : 'numbers'}` };
+  }
+
+  if (itemType === 'boolean') {
+    if (tokens.some((token) => token !== 'true' && token !== 'false')) {
+      return { error: 'Enter comma-separated true or false values' };
+    }
+    return { values: tokens.map((token) => token === 'true') };
+  }
+
+  return { values: tokens };
+}
+
+function PrimitiveArrayInput({
+  id,
+  value,
+  itemSchema,
+  placeholder,
+  readOnly,
+  onChange,
+}: {
+  id: string;
+  value: unknown;
+  itemSchema?: Record<string, unknown>;
+  placeholder?: string;
+  readOnly: boolean;
+  onChange: (value: unknown[]) => void;
+}) {
+  const formattedValue = formatArrayValue(value);
+  const [draft, setDraft] = useState(formattedValue);
+  const [error, setError] = useState<string | null>(null);
+
+  useEffect(() => {
+    setDraft(formattedValue);
+    setError(null);
+  }, [formattedValue]);
+
+  return (
+    <>
+      <Input
+        id={id}
+        type="text"
+        value={draft}
+        onChange={(event) => {
+          const nextDraft = event.target.value;
+          const parsed = parseArrayValue(nextDraft, itemSchema);
+          setDraft(nextDraft);
+          setError(parsed.error ?? null);
+          if (parsed.values) onChange(parsed.values);
+        }}
+        placeholder={placeholder || 'Enter comma-separated values'}
+        readOnly={readOnly}
+        disabled={readOnly}
+        aria-invalid={error ? true : undefined}
+        aria-describedby={error ? `${id}-error` : undefined}
+      />
+      {error ? (
+        <p id={`${id}-error`} role="alert" className="text-xs text-destructive">
+          {error}
+        </p>
+      ) : (
+        <p className="text-xs text-muted-foreground">Enter values separated by commas</p>
+      )}
+    </>
+  );
+}
+
+function JsonObjectEditor({
+  id,
+  value,
+  readOnly,
+  onChange,
+}: {
+  id: string;
+  value: unknown;
+  readOnly: boolean;
+  onChange: (value: Record<string, unknown>) => void;
+}) {
+  const formattedValue = useMemo(() => {
+    try {
+      return JSON.stringify(value, null, 2);
+    } catch {
+      return '';
+    }
+  }, [value]);
+  const [draft, setDraft] = useState(formattedValue);
+  const [error, setError] = useState<string | null>(null);
+
+  useEffect(() => {
+    setDraft(formattedValue);
+    setError(null);
+  }, [formattedValue]);
+
+  return (
+    <>
+      <Textarea
+        id={id}
+        aria-label="JSON object"
+        value={draft}
+        onChange={(event) => {
+          const nextDraft = event.target.value;
+          setDraft(nextDraft);
+          try {
+            const parsed = JSON.parse(nextDraft) as unknown;
+            if (!isRecord(parsed)) throw new Error('Value must be a JSON object');
+            setError(null);
+            onChange(parsed);
+          } catch (cause) {
+            setError(cause instanceof Error ? cause.message : 'Enter a valid JSON object');
+          }
+        }}
+        readOnly={readOnly}
+        disabled={readOnly}
+        aria-invalid={error ? true : undefined}
+        aria-describedby={error ? `${id}-error` : undefined}
+        className="min-h-24 font-mono text-xs"
+      />
+      {error ? (
+        <p id={`${id}-error`} role="alert" className="text-xs text-destructive">
+          {error}
+        </p>
+      ) : null}
+    </>
+  );
+}
+
+function defaultObjectValue(schema: Record<string, unknown> | undefined): Record<string, unknown> {
+  const properties = isRecord(schema?.properties)
+    ? (schema.properties as Record<string, Record<string, unknown>>)
+    : {};
+  return Object.fromEntries(
+    Object.entries(properties)
+      .filter(([, property]) => property.default !== undefined)
+      .map(([key, property]) => [key, property.default])
+  );
+}
+
+function ObjectArrayField({
+  id,
+  label,
+  value,
+  itemSchema,
+  validation,
+  readOnly,
+  onOpenLink,
+  onChange,
+}: {
+  id: string;
+  label: string;
+  value: unknown;
+  itemSchema?: Record<string, unknown>;
+  validation?: FieldConfig['validation'];
+  readOnly: boolean;
+  onOpenLink?: (href: string) => void;
+  onChange: (value: unknown[]) => void;
+}) {
+  const rows = Array.isArray(value) ? value : [];
+  const properties = isRecord(itemSchema?.properties)
+    ? (itemSchema.properties as Record<string, Record<string, unknown>>)
+    : null;
+  const declaredKeys = new Set(Object.keys(properties ?? {}));
+  const canAdd = validation?.maxItems === undefined || rows.length < validation.maxItems;
+  const canRemove = validation?.minItems === undefined || rows.length > validation.minItems;
+
+  return (
+    <div className="space-y-3" aria-label={`${label} rows`}>
+      {rows.length === 0 ? (
+        <p className="rounded-md border border-dashed p-3 text-sm text-muted-foreground">No rows</p>
+      ) : (
+        rows.map((row, index) => {
+          const rowId = `${id}-${index}`;
+          return (
+            // Schema arrays have no stable row identity. Every control below is
+            // fully controlled from the indexed row, so preserving the index is
+            // preferable to remounting the row on every edit.
+            // biome-ignore lint/suspicious/noArrayIndexKey: schema rows have no stable id
+            <fieldset key={index} className="rounded-md border p-3">
+              <legend className="px-1 text-xs font-medium text-muted-foreground">
+                {label} row {index + 1}
+              </legend>
+              {properties && isRecord(row) ? (
+                <DynamicConnectorForm
+                  schema={{ type: 'object', properties, required: itemSchema?.required }}
+                  initialValues={row}
+                  onValuesChange={(nextValues) => {
+                    const undeclaredValues = Object.fromEntries(
+                      Object.entries(row).filter(([key]) => !declaredKeys.has(key))
+                    );
+                    const nextRows = [...rows];
+                    nextRows[index] = { ...undeclaredValues, ...nextValues };
+                    onChange(nextRows);
+                  }}
+                  onOpenLink={onOpenLink}
+                  fieldIdPrefix={`${rowId}-`}
+                  readOnly={readOnly}
+                />
+              ) : (
+                <JsonObjectEditor
+                  id={`${rowId}-json`}
+                  value={row}
+                  readOnly={readOnly}
+                  onChange={(nextValue) => {
+                    const nextRows = [...rows];
+                    nextRows[index] = nextValue;
+                    onChange(nextRows);
+                  }}
+                />
+              )}
+              {readOnly ? null : (
+                <div className="mt-2 flex justify-end">
+                  <Button
+                    type="button"
+                    variant="ghost"
+                    size="sm"
+                    aria-label={`Remove ${label} row ${index + 1}`}
+                    disabled={!canRemove}
+                    onClick={() => onChange(rows.filter((_, rowIndex) => rowIndex !== index))}
+                  >
+                    <Trash2 className="mr-1.5 h-4 w-4" />
+                    Remove
+                  </Button>
+                </div>
+              )}
+            </fieldset>
+          );
+        })
+      )}
+      {readOnly ? null : (
+        <Button
+          type="button"
+          variant="outline"
+          size="sm"
+          aria-label={`Add ${label} row`}
+          disabled={!canAdd}
+          onClick={() => onChange([...rows, defaultObjectValue(itemSchema)])}
+        >
+          <Plus className="mr-1.5 h-4 w-4" />
+          Add row
+        </Button>
+      )}
+    </div>
+  );
+}

