+
+export function isSchemaRecord(
+	value: unknown,
+): value is Record<string, unknown> {
+	return typeof value === "object" && value !== null && !Array.isArray(value);
+}
+
+function formatArrayValue(value: unknown): string {
+	return Array.isArray(value)
+		? value.map((item) => String(item)).join(", ")
+		: "";
+}
+
+function parseArrayValue(
+	text: string,
+	itemType: unknown,
+): { values?: unknown[]; error?: string } {
+	const tokens = text
+		.split(",")
+		.map((item) => item.trim())
+		.filter(Boolean);
+
+	if (itemType === "number" || itemType === "integer") {
+		const values = tokens.map(Number);
+		const valid = values.every((value) =>
+			itemType === "integer"
+				? Number.isInteger(value)
+				: Number.isFinite(value),
+		);
+		return valid
+			? { values }
+			: {
+					error: `Enter comma-separated ${
+						itemType === "integer" ? "integers" : "numbers"
+					}`,
+				};
+	}
+
+	if (itemType === "boolean") {
+		if (tokens.some((token) => token !== "true" && token !== "false")) {
+			return { error: "Enter comma-separated true or false values" };
+		}
+		return { values: tokens.map((token) => token === "true") };
+	}
+
+	return { values: tokens };
+}
+
+export function SchemaPrimitiveArrayInput({
+	id,
+	value,
+	itemType,
+	placeholder,
+	readOnly = false,
+	showHelp = true,
+	onChange,
